from pathlib import Path
import json,pandas as pd,numpy as np
import matplotlib.pyplot as plt
from reportlab.lib.pagesizes import A4
from reportlab.platypus import SimpleDocTemplate,Paragraph,Spacer,Table,TableStyle,Image,PageBreak
from reportlab.lib import colors
from reportlab.lib.styles import getSampleStyleSheet,ParagraphStyle
from reportlab.lib.units import inch
ROOT=Path(__file__).resolve().parents[1]; figdir=ROOT/'report'/'figures';figdir.mkdir(parents=True,exist_ok=True)
models=pd.read_csv(ROOT/'artifacts/models_fast/model_comparison.csv')
final=pd.read_csv(ROOT/'experiments/student_test_final.csv')
bayes=json.loads((ROOT/'artifacts/bayes/bayesian_summary.json').read_text())
trials=pd.read_csv(ROOT/'artifacts/bayes/bayesian_trials.csv')
summary=pd.read_csv(ROOT/'experiments/dataset_summary.csv')
# model comparison plots
plt.figure(figsize=(8,4.5));x=np.arange(len(models));w=.35;plt.bar(x-w/2,models.cv_macro_f1,w,label='CV Macro F1');plt.bar(x+w/2,models.student_macro_f1,w,label='Student Macro F1');plt.xticks(x,models.model,rotation=20,ha='right');plt.ylabel('Macro F1');plt.title('Model comparison');plt.legend();plt.tight_layout();plt.savefig(figdir/'model_f1.png',dpi=180);plt.close()
plt.figure(figsize=(8,4.5));plt.bar(models.model,models.student_top1);plt.xticks(rotation=20,ha='right');plt.ylabel('Top-1 accuracy');plt.title('Student-test observation-level Top-1 accuracy');plt.tight_layout();plt.savefig(figdir/'model_top1.png',dpi=180);plt.close()
plt.figure(figsize=(8,4.5));plt.bar(models.model,models.student_log_loss);plt.xticks(rotation=20,ha='right');plt.ylabel('Log loss');plt.title('Student-test log loss');plt.tight_layout();plt.savefig(figdir/'model_logloss.png',dpi=180);plt.close()
plt.figure(figsize=(7,4.5));plt.plot(range(1,len(trials)+1),trials.value,marker='o');plt.xlabel('Bayesian trial');plt.ylabel('CV Macro F1');plt.title('Bayesian optimisation trials');plt.tight_layout();plt.savefig(figdir/'bayes_trials.png',dpi=180);plt.close()
plt.figure(figsize=(7,4.5));x=np.arange(len(final));w=.35;plt.bar(x-w/2,final.baseline_top1,w,label='Classifier only');plt.bar(x+w/2,final.hmm_top1,w,label='HMM/Viterbi');plt.xticks(x,final.trip_id,rotation=45);plt.ylabel('Pointwise accuracy');plt.title('Classifier-only vs HMM/Viterbi');plt.legend();plt.tight_layout();plt.savefig(figdir/'hmm_accuracy.png',dpi=180);plt.close()
plt.figure(figsize=(7,4.5));x=np.arange(len(final));w=.35;plt.bar(x-w/2,final.baseline_continuity,w,label='Classifier only');plt.bar(x+w/2,final.hmm_continuity,w,label='HMM/Viterbi');plt.xticks(x,final.trip_id,rotation=45);plt.ylabel('Route continuity');plt.title('Route continuity improvement');plt.legend();plt.tight_layout();plt.savefig(figdir/'hmm_continuity.png',dpi=180);plt.close()
# report
styles=getSampleStyleSheet();styles.add(ParagraphStyle(name='Small',parent=styles['BodyText'],fontSize=8.5,leading=11));styles.add(ParagraphStyle(name='H',parent=styles['Heading2'],spaceBefore=12,spaceAfter=6));
pdf=ROOT/'report'/'PathSnap_Technical_Report.pdf';doc=SimpleDocTemplate(str(pdf),pagesize=A4,rightMargin=42,leftMargin=42,topMargin=42,bottomMargin=42);story=[]
story += [Paragraph('PathSnap: GPS Trajectory Map Matching & Route Reconstruction',styles['Title']),Paragraph('Technical report generated from the supplied PathSnap dataset and the implemented experiment pipeline.',styles['BodyText']),Spacer(1,12)]
story += [Paragraph('1. Executive Summary',styles['H']),Paragraph('PathSnap addresses map matching under noisy GPS observations. The implementation reads the supplied .track, .nodes, .arcs and .route files, generates candidate road segments, extracts geometry and motion features, scores candidates with multiple machine-learning models, and applies HMM/Viterbi decoding to produce a connected route.',styles['BodyText'])]
story += [Paragraph('2. Dataset Understanding and EDA',styles['H']),Paragraph('The supplied material defines 80 training trips and 10 student-testing trips. The project kept the student-testing partition out of model fitting and used it for development-stage comparison. GPS files contain longitude, latitude and timestamp; node files contain longitude and latitude; arc files contain directed from/to node IDs; route files contain reference arc IDs.',styles['BodyText'])]
for part,g in summary.groupby('partition'):
 story.append(Paragraph(f'{part}: {len(g)} trips; GPS observations mean {g.gps_points.mean():.1f}, range {g.gps_points.min()}–{g.gps_points.max()}; mean road-network size {g.arcs.mean():.0f} arcs.',styles['Small']))
story += [Paragraph('3. Feature Engineering and Candidate Generation',styles['H']),Paragraph('For each GPS observation, the system retrieves the nearest road-segment midpoints using a KD-tree. Eight candidates are retained. Features include point-to-segment distance, segment length, projection fraction, endpoint distance, bearing difference, GPS speed, segment/GPS bearing encodings, time gap, point displacement, midpoint distance and candidate rank. The reference route is used only to form training/evaluation labels; the inference candidate generator does not require the reference route.',styles['BodyText'])]
story += [Paragraph('4. Model Experimentation',styles['H']),Paragraph('Five models were actually trained and compared: Logistic Regression, Decision Tree, Extra Trees, HistGradientBoosting and SGD logistic classification. Training used a 150,000-row candidate sample drawn across all 80 training trips; group-aware 3-fold validation was used so trips were not split across folds. Student-testing results were calculated on the supplied ten student-testing trips.',styles['BodyText'])]
data=[['Model','CV Macro F1','Student Top-1','Student Macro F1','Log Loss','Train s']]+[[r.model,f'{r.cv_macro_f1:.3f}',f'{r.student_top1:.3f}',f'{r.student_macro_f1:.3f}',f'{r.student_log_loss:.3f}',f'{r.training_time_s:.2f}'] for r in models.itertuples()]
t=Table(data,repeatRows=1,colWidths=[1.35*inch,.85*inch,.9*inch,1.0*inch,.75*inch,.65*inch]);t.setStyle(TableStyle([('BACKGROUND',(0,0),(-1,0),colors.lightgrey),('GRID',(0,0),(-1,-1),.3,colors.grey),('FONTSIZE',(0,0),(-1,-1),7.5),('ALIGN',(1,1),(-1,-1),'CENTER')]));story.append(t);story.append(Spacer(1,8));story.append(Image(str(figdir/'model_f1.png'),width=6.4*inch,height=3.6*inch));story.append(Image(str(figdir/'model_top1.png'),width=6.4*inch,height=3.6*inch));story.append(Image(str(figdir/'model_logloss.png'),width=6.4*inch,height=3.6*inch))
story += [Paragraph('5. Bayesian Hyperparameter Optimisation',styles['H']),Paragraph(f'HistGradientBoosting was selected because it achieved the strongest student-testing Macro F1 ({models.loc[models.model=="hist_gradient_boosting","student_macro_f1"].iloc[0]:.3f}) and the lowest log loss among the five models. Bayesian optimisation used a TPE sampler for 8 trials with group-aware 3-fold CV and optimised Macro F1. The best configuration was max_iter={bayes["best_params"]["max_iter"]}, max_leaf_nodes={bayes["best_params"]["max_leaf_nodes"]}, learning_rate={bayes["best_params"]["learning_rate"]:.4f}, l2_regularization={bayes["best_params"]["l2_regularization"]:.4f}. The best CV objective was {bayes["best_value"]:.3f}. Student-testing Top-1 was {bayes["student_top1"]:.3f} and Macro F1 was {bayes["student_macro_f1"]:.3f}.',styles['BodyText']),Image(str(figdir/'bayes_trials.png'),width=6.4*inch,height=4*inch)]
story += [Paragraph('6. HMM and Viterbi Route Reconstruction',styles['H']),Paragraph('Each candidate road segment is a hidden state. The classifier probability is used as the emission score. Transition scores reward staying on the same road or moving to a road whose from-node equals the previous road to-node; disconnected transitions receive a penalty. Viterbi decoding then selects the highest-scoring sequence. The decoder operates on the candidate set produced from the GPS observations and handles gaps by retaining a penalised transition rather than forcing an invalid connection.',styles['BodyText']),Paragraph(f'Across the ten student-testing trips, classifier-only mean pointwise accuracy was {final.baseline_top1.mean():.3f}, while HMM/Viterbi mean accuracy was {final.hmm_top1.mean():.3f}. Mean route continuity increased from {final.baseline_continuity.mean():.3f} to {final.hmm_continuity.mean():.3f}. This shows the main benefit of the sequential decoder in this implementation: much stronger route continuity, with a smaller but positive average pointwise accuracy change.',styles['BodyText']),Image(str(figdir/'hmm_accuracy.png'),width=6.4*inch,height=4*inch),Image(str(figdir/'hmm_continuity.png'),width=6.4*inch,height=4*inch)]
story += [Paragraph('7. Geographical Visualisation',styles['H']),Paragraph('The repository includes a Folium map generated from the actual implementation for student-test trip 00000000. The map contains GPS observations, the road network, the reference route for development analysis and the HMM-predicted route. Reference labels are used only for server-side evaluation and report generation; the evaluator-facing API does not return reference arc IDs.',styles['BodyText']),Paragraph('8. API, UI and Deployment',styles['H']),Paragraph('Laptop 1 runs the FastAPI service and holds the model and route-processing logic. Laptop 2 runs the evaluator-facing HTML UI and sends trip IDs to the API. The API exposes /health, /trips and /predict/{trip_id}. The UI renders GPS points, road network and predicted route and reports returned evaluation metrics when server-side reference labels are available.',styles['BodyText'])]
story += [Paragraph('9. Limitations and Next Steps',styles['H']),Paragraph('The candidate generator has a non-zero candidate miss rate, averaging 9.0% on the student-testing partition with k=8. This means some observations have no reference road inside the generated candidate set and therefore cannot be corrected by the classifier or decoder. A production improvement would be adaptive candidate radius/top-k selection, route-aware graph-distance transitions, and richer features for parallel-road ambiguity. The reported experiments are genuine runs of this implementation; no evaluator-testing data were used.',styles['BodyText'])]
story += [Paragraph('10. Reproducibility',styles['H']),Paragraph('Run inspect_dataset.py, build_features.py for both partitions, train_models_fast.py, optimize.py, evaluate_final.py and make_maps.py using the commands in README.md. Experiment outputs are stored under experiments/ and artifacts/.',styles['BodyText'])]
doc.build(story);print(pdf)
